package handler
import("encoding/json";"net/http";"strconv";"github.com/go-chi/chi/v5";"go-repair-center/internal/repository";"go-repair-center/internal/service";"go-repair-center/internal/transport/http/dto";"go-repair-center/internal/transport/http/middleware";"go-repair-center/internal/transport/http/response")
type QuotationHandler struct{*GenericHandler;quotes *service.QuotationService}
func NewQuotationHandler(quotes *service.QuotationService)*QuotationHandler{return &QuotationHandler{GenericHandler:NewGenericHandler(quotes,"quotation"),quotes:quotes}}
func(h *QuotationHandler)Routes(router chi.Router){router.Route("/quotations",func(resource chi.Router){h.Register(resource,"quotation:read","quotation:write");resource.With(middleware.Require("quotation:write")).Post("/versions",h.CreateVersion);resource.With(middleware.Require("quotation:read")).Get("/history/{repairOrderID}",h.History);resource.With(middleware.Require("quotation:write")).Post("/{id}/approve",h.Approve)})}
func(h *QuotationHandler)CreateVersion(w http.ResponseWriter,r *http.Request){var input dto.QuotationVersionRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};record:=repository.Record{"repair_order_id":input.RepairOrderID,"labor_fee":input.LaborFee,"parts_fee":input.PartsFee,"inspection_fee":input.InspectionFee,"other_fee":input.OtherFee};items:=make([]repository.Record,len(input.Items));for i,item:=range input.Items{items[i]=repository.Record(item)};result,err:=h.quotes.CreateVersion(r.Context(),record,items,middleware.UserID(r.Context()),r.Header.Get("Idempotency-Key"));if err!=nil{writeError(w,r,err);return};response.Created(w,result,middleware.RequestID(r.Context()))}
func(h *QuotationHandler)History(w http.ResponseWriter,r *http.Request){id,_:=strconv.ParseInt(chi.URLParam(r,"repairOrderID"),10,64);items,err:=h.quotes.History(r.Context(),id);if err!=nil{writeError(w,r,err);return};response.Success(w,items,middleware.RequestID(r.Context()))}
func(h *QuotationHandler)Approve(w http.ResponseWriter,r *http.Request){id,_:=strconv.ParseInt(chi.URLParam(r,"id"),10,64);var input dto.ApprovalRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};result,err:=h.quotes.Approve(r.Context(),id,middleware.UserID(r.Context()),input.Approved);if err!=nil{writeError(w,r,err);return};response.Success(w,result,middleware.RequestID(r.Context()))}
